package org.apache.fluo.core.util;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

import org.apache.fluo.api.client.FluoClient;
import org.apache.fluo.api.client.FluoFactory;
import org.apache.fluo.api.config.SimpleConfiguration;
import org.apache.fluo.api.exceptions.FluoException;
import org.junit.After;
import org.junit.Test;
import org.mockito.MockedStatic;
import org.mockito.Mockito;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;

/**
 * Tests that {@link ScanUtil#scanFluo} properly catches FluoException from
 * {@link FluoFactory#newClient} and prints "Scan failed" before calling System.exit(-1).
 */
public class ScanUtilFluoClientInitExceptionTest {

  private final ByteArrayOutputStream stderrCapture = new ByteArrayOutputStream();
  private final PrintStream originalErr = System.err;

  @After
  public void restoreStderr() {
    System.setErr(originalErr);
  }

  @Test
  public void testFluoExceptionFromNewClientIsCaughtAndPrinted() {
    // Capture stderr
    System.setErr(new PrintStream(stderrCapture));

    boolean caughtFluoException = false;

    try (MockedStatic<FluoFactory> mockedFluoFactory = Mockito.mockStatic(FluoFactory.class)) {
      mockedFluoFactory.when(() -> FluoFactory.newClient((SimpleConfiguration) any()))
          .thenThrow(new FluoException("test connection failure"));

      ScanUtil.ScanOpts opts =
          new ScanUtil.ScanOpts(null, null, null, null, null, false, true, false);

      try {
        ScanUtil.scanFluo(opts, null);
      } catch (FluoException e) {
        // This is the BUG: the FluoException from newClient() propagates up
        // because the catch block in scanFluo() is nested inside the try-with-resources
        // and does NOT catch exceptions thrown during resource initialization.
        // Correct behavior: scanFluo should catch this, print "Scan failed", and exit.
        caughtFluoException = true;
      }
    }

    // If we reached here without throwing, scanFluo properly caught the exception
    // and called System.exit(-1). If caughtFluoException is true, the bug exists.
    assertTrue("Bug confirmed: FluoException from newClient() was NOT caught by scanFluo(). "
        + "Expected the exception to be caught, 'Scan failed' printed to stderr, "
        + "and System.exit(-1) called. Instead, FluoException propagated up. " + "stderr was: "
        + stderrCapture.toString(), !caughtFluoException);
  }
}

