package org.apache.fluo.core.util;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Collections;

import org.apache.accumulo.core.client.Connector;
import org.apache.accumulo.core.client.Scanner;
import org.apache.accumulo.core.security.Authorizations;
import org.apache.fluo.api.config.FluoConfiguration;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.mockito.MockedStatic;

public class ScanUtilTest {

  private MockedStatic<AccumuloUtil> accumuloUtilMock;

  @Before
  public void setUp() {
    accumuloUtilMock = mockStatic(AccumuloUtil.class);
  }

  @After
  public void tearDown() {
    accumuloUtilMock.close();
  }

  @Test
  public void scanAccumuloShouldCloseScanner() throws Exception {
    // Arrange
    Connector mockConnector = mock(Connector.class);
    Scanner mockScanner = mock(Scanner.class);
    FluoConfiguration mockConfig = mock(FluoConfiguration.class);

    // Configure mocks
    when(mockConfig.getAccumuloTable()).thenReturn("test_table");
    when(mockConnector.createScanner("test_table", Authorizations.EMPTY)).thenReturn(mockScanner);
    when(mockScanner.iterator()).thenReturn(Collections.emptyIterator());
    accumuloUtilMock.when(() -> AccumuloUtil.getConnector(mockConfig)).thenReturn(mockConnector);

    // Use valid range: "a" < "z"
    ScanUtil.ScanOpts options =
        new ScanUtil.ScanOpts("a", "z", Collections.emptyList(), null, null, false, false, false);

    // Act
    ScanUtil.scanAccumulo(options, mockConfig);

    // Assert - Scanner should be closed after use
    verify(mockScanner, times(1)).close();
  }
}

